<script>
(function(){const ep='process-offertory.php';let rows=[];const q=s=>document.querySelector(s),qa=s=>Array.from(document.querySelectorAll(s));const esc=v=>String(v??'').replace(/[&<>"']/g,m=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#039;'}[m]));const money=v=>'UGX '+Number(v||0).toLocaleString();function alert(el,msg,type='success'){el.className='ajax-alert '+(type==='error'?'error':'success');el.textContent=msg}function clear(el){el.className='ajax-alert';el.textContent=''}function open(id){q('#backdrop').classList.add('show');q(id).classList.add('show');document.body.style.overflow='hidden'}function close(){qa('.ajax-modal,.ajax-modal-backdrop').forEach(x=>x.classList.remove('show'));document.body.style.overflow=''}async function req(url,opt={}){let r=await fetch(url,Object.assign({headers:{'X-Requested-With':'XMLHttpRequest'}},opt));let t=await r.text();try{return JSON.parse(t)}catch(e){throw new Error('Invalid server response: '+t.slice(0,180))}}async function post(f){return req(ep,{method:'POST',body:new FormData(f)})}function calc(){let t=(parseFloat(q('#envelope_total').value)||0)+(parseFloat(q('#loose_total').value)||0)+(parseFloat(q('#extra').value)||0);q('#totalDisplay').textContent=t.toLocaleString()}function stats(s){q('#stMonth').textContent=money(s.month_total);q('#stYear').textContent=money(s.year_total);q('#stAll').textContent=money(s.all_total)}function render(){let term=q('#searchBox').value.toLowerCase();let data=rows.filter(r=>Object.values(r).join(' ').toLowerCase().includes(term));q('#tbody').innerHTML=data.length?data.map((r,i)=>`<tr><td>${i+1}</td><td>${esc(r.service_date)}</td><td><span class="badge badge-primary">${esc(r.service_type)}</span></td><td>${Number(r.envelope_total||0).toLocaleString()}</td><td>${Number(r.loose_total||0).toLocaleString()}</td><td class="font-weight-bold text-success">${Number(r.total_amount||0).toLocaleString()}</td><td>${esc(r.counted_by||'')}</td><td>${esc(r.witnessed_by||'')}</td><td><div class="act"><button class="btn btn-sm btn-info" data-act="view" data-id="${r.id}"><i class="fas fa-eye"></i></button><button class="btn btn-sm btn-warning" data-act="edit" data-id="${r.id}"><i class="fas fa-edit"></i></button><a class="btn btn-sm btn-secondary" href="receipt.php?id=${r.id}" target="_blank" title="Receipt"><i class="fas fa-file-pdf"></i></a><button class="btn btn-sm btn-danger" data-act="delete" data-id="${r.id}"><i class="fas fa-trash"></i></button></div></td></tr>`).join(''):'<tr><td colspan="9">No offertory records found.</td></tr>'}async function load(){let d=await req(ep+'?action=list&month='+encodeURIComponent(q('#monthFilter').value));if(!d.success)throw new Error(d.message);rows=d.items||[];stats(d.stats||{});render()}function reset(){q('#offForm').reset();q('#oid').value='';q('#service_date').value=new Date().toISOString().slice(0,10);q('#extra').value=0;q('#formTitle').textContent='Record Offertory';clear(q('#formAlert'));calc()}async function get(id){let d=await req(ep+'?action=get&id='+id);if(!d.success)throw new Error(d.message);return d.item}async function edit(id){reset();let r=await get(id);q('#formTitle').textContent='Edit Offertory';q('#oid').value=r.id;q('#service_date').value=r.service_date||'';q('#service_type').value=r.service_type||'Sunday Service';q('#envelope_total').value=r.envelope_total||0;q('#loose_total').value=r.loose_total||0;q('#extra').value=0;q('#counted_by').value=r.counted_by||'';q('#witnessed_by').value=r.witnessed_by||'';q('#notes').value=r.notes||'';calc();open('#formModal')}async function view(id){let r=await get(id);q('#viewBox').innerHTML=`<div class="detail-grid">${[['Date',r.service_date],['Service Type',r.service_type],['Envelope',money(r.envelope_total)],['Loose',money(r.loose_total)],['Total',money(r.total_amount)],['Counted By',r.counted_by],['Witnessed By',r.witnessed_by],['Notes',r.notes]].map(x=>`<div class="detail"><b>${esc(x[0])}</b>${esc(x[1]||'—')}</div>`).join('')}</div><div class="mt-3"><a href="receipt.php?id=${r.id}" target="_blank" class="btn btn-secondary"><i class="fas fa-file-pdf"></i> Download Receipt</a></div>`;open('#viewModal')}q('#btnAdd').onclick=()=>{reset();open('#formModal')};q('#btnFilter').onclick=()=>load().catch(e=>alert(q('#pageAlert'),e.message,'error'));q('#searchBox').oninput=render;q('#backdrop').onclick=close;qa('.close-modal').forEach(b=>b.onclick=close);qa('.calc').forEach(i=>i.oninput=calc);document.addEventListener('click',e=>{let b=e.target.closest('[data-act]');if(!b)return;let id=b.dataset.id;if(b.dataset.act==='view')view(id).catch(er=>alert(q('#pageAlert'),er.message,'error'));if(b.dataset.act==='edit')edit(id).catch(er=>alert(q('#pageAlert'),er.message,'error'));if(b.dataset.act==='delete'){q('#deleteId').value=id;clear(q('#deleteAlert'));open('#deleteModal')}});q('#offForm').onsubmit=async e=>{e.preventDefault();let d=await post(e.target).catch(er=>({success:false,message:er.message}));if(!d.success)return alert(q('#formAlert'),d.message,'error');close();alert(q('#pageAlert'),d.message);load()};q('#deleteForm').onsubmit=async e=>{e.preventDefault();let d=await post(e.target).catch(er=>({success:false,message:er.message}));if(!d.success)return alert(q('#deleteAlert'),d.message,'error');close();alert(q('#pageAlert'),d.message);load()};load().catch(e=>alert(q('#pageAlert'),e.message,'error'))})();
</script>
